<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Viaje compartido</title><style>body{font-family:Segoe UI;background:#0f172a;color:white;padding:24px}.card{max-width:700px;margin:auto;background:#1e293b;padding:25px;border-radius:14px}b{color:#38bdf8}</style>    @include('partials.pwa-head')
</head><body><div class="card"><h1>Seguimiento de viaje #{{ $trip->id }}</h1><p>Estado: <b id="status">{{ $trip->status }}</b></p><p>Origen: {{ $trip->origin }}</p><p>Destino: {{ $trip->destination }}</p><p>Conductor: {{ $trip->driver?->name ?? 'Pendiente' }}</p><p id="location">La ubicacion se mostrara cuando este disponible.</p><p>Este enlace vence {{ $share->expires_at->diffForHumans() }}.</p></div><script>async function update(){const r=await fetch(location.href,{headers:{Accept:'application/json'}}).catch(()=>null);if(!r||!r.ok)return;const d=await r.json();document.getElementById('status').textContent=d.status;document.getElementById('location').textContent=d.latitude&&d.longitude?'Ubicacion actual del conductor: '+d.latitude.toFixed(5)+', '+d.longitude.toFixed(5):'Ubicacion reciente no disponible.';}update();setInterval(update,10000);</script>    @include('partials.pwa-script')
